{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>About {{BUSINESS_NAME}} • Brighter Tides Wellness</title>
  <meta name="description" content="Meet the ocean-inspired wellness studio helping high-achievers feel grounded, playful, and powerfully well." />
  <style>
    :root{
      --teal:#0E6B69;
      --teal-600:#0c5f5d;
      --teal-700:#0a5250;
      --sand:#E8DCC6;
      --cream:#FAF8F5;
      --ink:#0F2A2A;
      --muted:#597776;
      --accent:#FF7A59;
      --accent-600:#e3684b;
      --white:#ffffff;
      --shadow:0 10px 30px rgba(14,107,105,0.15);
      --radius-l:20px; --radius-m:12px; --radius-s:8px;
    }
    *{box-sizing:border-box}
    html{scroll-behavior:smooth}
    body{margin:0;font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, Apple Color Emoji, Segoe UI Emoji; color:var(--ink); background:var(--cream);}    
    a{color:var(--teal); text-decoration:none}
    a:focus{outline:3px solid var(--accent); outline-offset:2px}
    .sr-only{position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); white-space:nowrap; border:0}
    header{position:sticky; top:0; z-index:50; background:linear-gradient(0deg, rgba(250,248,245,0.85), rgba(250,248,245,0.85)); backdrop-filter: blur(8px); border-bottom:1px solid rgba(14,107,105,0.08)}
    .wrap{max-width:1160px; margin:0 auto; padding:0 20px}
    .nav{display:flex; align-items:center; justify-content:space-between; gap:16px; min-height:72px}
    .brand{display:flex; align-items:center; gap:12px; font-weight:800; letter-spacing:.3px}
    .brand-logo{width:36px; height:36px; border-radius:12px; background: radial-gradient(120% 120% at 20% 20%, var(--accent) 0%, var(--accent-600) 35%, var(--teal) 36%, var(--teal-700) 100%); box-shadow: var(--shadow)}
    .brand b{color:var(--teal)}
    nav ul{display:flex; gap:22px; list-style:none; padding:0; margin:0}
    nav a{padding:10px 6px; border-radius:8px}
    nav a:hover{background:rgba(14,107,105,0.08)}
    .cta{background:var(--accent); color:white; padding:12px 16px; border-radius:999px; font-weight:700; box-shadow: var(--shadow)}
    .cta:hover{background:var(--accent-600)}
    .menu-btn{display:none; background:var(--teal); color:#fff; border:0; padding:10px 12px; border-radius:10px}

    .hero{position:relative; overflow:hidden; background: radial-gradient(1200px 400px at 10% -10%, var(--sand), transparent 60%), radial-gradient(800px 400px at 110% 10%, rgba(14,107,105,0.08), transparent 60%), var(--cream);}
    .hero .wrap{display:grid; grid-template-columns: 1.2fr 1fr; gap:40px; align-items:center; padding:64px 20px}
    .pill{display:inline-flex; align-items:center; gap:8px; padding:8px 12px; border-radius:999px; background:#fff; border:1px solid rgba(14,107,105,0.12); color:var(--muted); font-weight:600}
    .h1{font-size:clamp(28px,4.5vw,48px); line-height:1.05; margin:14px 0 12px; color:var(--teal)}
    .lead{font-size:18px; color:var(--muted); max-width:62ch}
    .hero-card{background:#fff; border:1px solid rgba(14,107,105,0.12); border-radius:var(--radius-l); padding:20px; display:grid; grid-template-columns:72px 1fr; gap:16px; align-items:center; box-shadow: var(--shadow)}
    .hero-visual{position:relative}
    .hero-blob{position:absolute; inset:-40px -20px auto auto; width:280px; height:280px; border-radius:50%; background: radial-gradient(140px 140px at 60% 40%, rgba(255,122,89,0.25), transparent 70%), radial-gradient(180px 200px at 40% 60%, rgba(14,107,105,0.15), transparent 70%)}
    .hero-img{position:relative; width:100%; max-width:420px; border-radius:20px; background:#fff; border:1px solid rgba(14,107,105,0.12); padding:16px}
    .hero-img img{width:100%; height:auto; display:block}

    .section{padding:72px 0}
    .section .eyebrow{letter-spacing:.12em; text-transform:uppercase; color:var(--muted); font-size:12px; font-weight:800}
    .section h2{font-size:clamp(22px,3.2vw,36px); margin:10px 0 12px; color:var(--teal)}
    .grid-3{display:grid; grid-template-columns:repeat(3,1fr); gap:22px}
    .grid-2{display:grid; grid-template-columns:repeat(2,1fr); gap:22px}
    .card{background:#fff; border:1px solid rgba(14,107,105,0.12); border-radius:16px; padding:20px; box-shadow: var(--shadow)}
    .icon{width:42px; height:42px; display:inline-grid; place-items:center; border-radius:12px; background:var(--sand); color:var(--teal)}
    .check{color:var(--teal)}
    .mark{background: linear-gradient( to right, rgba(255,122,89,0.2), rgba(232,220,198,0.6)); padding:2px 6px; border-radius:8px}

    .tiers .tier{display:flex; flex-direction:column; gap:10px}
    .tier h3{margin:0; font-size:20px; color:var(--ink)}
    .tier .price{font-weight:800; color:var(--teal)}
    .tier ul{margin:0; padding-left:18px; color:var(--muted)}

    .testimonials .t{display:flex; flex-direction:column; gap:10px}
    .stars{color:#f4a261}

    .faq .q{display:flex; align-items:center; justify-content:space-between; width:100%; background:#fff; border:1px solid rgba(14,107,105,0.12); border-radius:12px; padding:16px; text-align:left; font-weight:700}
    .faq .a{padding:14px 16px 4px; color:var(--muted)}

    .newsletter{background: linear-gradient(180deg, rgba(232,220,198,0.6), rgba(250,248,245,1)); border:1px solid rgba(14,107,105,0.12); border-radius:20px; padding:24px}
    .newsletter form{display:flex; gap:12px; flex-wrap:wrap}
    input[type="email"], input[type="text"], input[type="tel"]{border:1px solid rgba(14,107,105,0.2); padding:12px 14px; border-radius:12px; font-size:16px; min-width:260px}
    .hint{font-size:12px; color:#9b6b5a}

    .cta-row{display:flex; align-items:center; justify-content:space-between; gap:20px; background:#fff; border:1px solid rgba(14,107,105,0.12); border-radius:20px; padding:20px; box-shadow: var(--shadow)}

    footer{margin-top:72px; background: linear-gradient(0deg, rgba(14,107,105,0.06), rgba(14,107,105,0.02)); border-top:1px solid rgba(14,107,105,0.1)}
    .foot{display:grid; grid-template-columns:2fr 1fr 1fr; gap:24px; padding:36px 20px}
    .foot small{color:var(--muted)}
    .subtle{color:var(--muted)}

    /* Responsive */
    @media (max-width: 960px){
      nav ul{display:none}
      .menu-btn{display:inline-flex; align-items:center; gap:8px}
      .nav[data-open="true"] ul{display:flex; position:absolute; top:72px; left:0; right:0; flex-direction:column; background:#fff; border-bottom:1px solid rgba(14,107,105,0.1); padding:12px 20px 20px}
      .hero .wrap{grid-template-columns:1fr; padding-top:36px}
      .grid-3{grid-template-columns:1fr}
      .grid-2{grid-template-columns:1fr}
      .foot{grid-template-columns:1fr;}
      .cta-row{flex-direction:column; align-items:flex-start}
    }
  </style>
</head>
<body>
  <a class="sr-only" href="#main">Skip to content</a>
  <header>
    <div class="wrap nav" role="navigation" aria-label="Main">
      <a class="brand" href="index.html" aria-label="Home — {{BUSINESS_NAME}}">
        <span class="brand-logo" aria-hidden="true"></span>
        <span><b>Brighter Tides</b> Wellness</span>
      </a>
      <button class="menu-btn" data-nav-toggle aria-controls="site-menu" aria-expanded="false">Menu</button>
      <nav id="site-menu">
        <ul>
          <li><a href="index.html">Home</a></li>
          <li><a aria-current="page" href="about.html">About</a></li>
          <li><a href="services.html">Services</a></li>
          <li><a href="programs.html">Programs</a></li>
          <li><a href="pricing.html">Pricing</a></li>
          <li><a href="testimonials.html">Testimonials</a></li>
          <li><a href="contact.html">Contact</a></li>
          <li><a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main id="main">
    <section class="hero" aria-labelledby="about-hero">
      <div class="wrap">
        <div>
          <span class="pill">Playful Premium Care • Ocean-inspired</span>
          <h1 class="h1" id="about-hero">About {{BUSINESS_NAME}}</h1>
          <p class="lead">{{TAGLINE}}. At Brighter Tides Wellness, we blend evidence-based coaching with a lighthearted, human touch—so healthy change finally feels doable and even a little fun.</p>
          <div class="hero-card" role="group" aria-label="Coach highlight">
            <img src="assets/img/avatar.svg" alt="Coach portrait illustration" width="72" height="72" style="border-radius:14px; background:var(--sand); padding:6px"/>
            <div>
              <strong>{{COACH_NAME}}, <span class="subtle">{{CREDENTIALS}}</span></strong>
              <p class="subtle" style="margin:6px 0 0">Founder, Brighter Tides. Guiding high-achievers to regulate stress, rebuild energy, and rediscover play.</p>
            </div>
          </div>
        </div>
        <div class="hero-visual">
          <div class="hero-blob" aria-hidden="true"></div>
          <div class="hero-img">
            <img src="assets/img/hero.svg" alt="Abstract hero illustration with waves and sun"/>
          </div>
        </div>
      </div>
    </section>

    <section class="section" aria-labelledby="story">
      <div class="wrap grid-2">
        <div>
          <span id="story" class="eyebrow">Our story</span>
          <h2>Where science meets shoreline</h2>
          <p>Brighter Tides began on morning walks along the coast—when our founder, {{COACH_NAME}}, realized sustainable wellness arrives in <span class="mark">gentle waves</span>, not overnight overhauls. With {{CREDENTIALS}}, {{COACH_NAME}} created a coaching studio that honors your nervous system, your schedule, and your joy.</p>
          <p>We pair behavior design, sleep and stress protocols, and nourishing routines with playful accountability. It’s wellness for real life—commutes, kids, deadlines and all.</p>
        </div>
        <div class="card">
          <h3 style="margin-top:0">The TIDES Method</h3>
          <ul>
            <li><strong>Tune-in:</strong> map rhythms, triggers, and goals.</li>
            <li><strong>Integrate:</strong> stack tiny habits into daily anchors.</li>
            <li><strong>Deepen:</strong> iterate with biofeedback and reflection.</li>
            <li><strong>Embody:</strong> rituals that stick—without perfectionism.</li>
          </ul>
          <p class="subtle">It’s simple on purpose. Complex lives need simple systems.</p>
        </div>
      </div>
    </section>

    <section class="section" aria-labelledby="benefits">
      <div class="wrap">
        <span id="benefits" class="eyebrow">Benefits</span>
        <h2>Results you can feel and measure</h2>
        <div class="grid-3">
          <div class="card">
            <span class="icon" aria-hidden="true">💤</span>
            <h3 style="margin:10px 0">Deeper Sleep</h3>
            <p class="subtle">Reset circadian cues and pre-bed rituals for real rest.</p>
          </div>
          <div class="card">
            <span class="icon" aria-hidden="true">🌿</span>
            <h3 style="margin:10px 0">Calmer Nervous System</h3>
            <p class="subtle">Breath, micro-breaks, and mindful dosing of inputs.</p>
          </div>
          <div class="card">
            <span class="icon" aria-hidden="true">⚡️</span>
            <h3 style="margin:10px 0">Steady Energy</h3>
            <p class="subtle">Meal timing, hydration, and movement that spark.</p>
          </div>
        </div>
      </div>
    </section>

    <section class="section tiers" aria-labelledby="tiers">
      <div class="wrap">
        <span id="tiers" class="eyebrow">Program tiers</span>
        <h2>Choose your current tide</h2>
        <div class="grid-3">
          <div class="card tier">
            <h3>Clarity Call</h3>
            <span class="price">Free • 20 minutes</span>
            <p class="subtle">A friendly consult to map goals and next steps.</p>
            <ul>
              <li>Fit assessment</li>
              <li>Personalized recommendation</li>
            </ul>
            <a class="cta" href="book.html">Book now</a>
          </div>
          <div class="card tier">
            <h3>Foundations Month</h3>
            <span class="price">4 sessions</span>
            <p class="subtle">Dial in sleep, stress, and core routines.</p>
            <ul>
              <li>Weekly 50-min 1:1</li>
              <li>Simple habit plan</li>
              <li>Messaging support</li>
            </ul>
            <a class="cta" href="programs.html">Explore details</a>
          </div>
          <div class="card tier">
            <h3>Transform • 12 Weeks</h3>
            <span class="price">Signature</span>
            <p class="subtle">Comprehensive coaching with data-informed tweaks.</p>
            <ul>
              <li>Bi-weekly 1:1 sessions</li>
              <li>Biometrics & habit dashboard</li>
              <li>Customized protocols</li>
            </ul>
            <a class="cta" href="pricing.html">See pricing</a>
          </div>
        </div>
      </div>
    </section>

    <section class="section testimonials" aria-labelledby="voices">
      <div class="wrap">
        <span id="voices" class="eyebrow">Client voices</span>
        <h2>Stories from our shore</h2>
        <div class="grid-3">
          <div class="card t">
            <div class="stars" aria-label="5 out of 5 stars">★★★★★</div>
            <p>My sleep went from chaotic to consistent in three weeks. The playful accountability kept me going.</p>
            <small class="subtle">— M., Product Lead</small>
          </div>
          <div class="card t">
            <div class="stars" aria-label="5 out of 5 stars">★★★★★</div>
            <p>I finally have a morning routine that survives meetings and kids. I feel like myself again.</p>
            <small class="subtle">— R., Attorney</small>
          </div>
          <div class="card t">
            <div class="stars" aria-label="5 out of 5 stars">★★★★★</div>
            <p>Data without judgment. Care without fluff. Exactly what I needed to change for good.</p>
            <small class="subtle">— S., Founder</small>
          </div>
        </div>
      </div>
    </section>

    <section class="section faq" aria-labelledby="faq">
      <div class="wrap">
        <span id="faq" class="eyebrow">FAQ</span>
        <h2>Answers, without the overwhelm</h2>
        <div class="grid-2" role="list">
          <div class="card" role="listitem">
            <button class="q" aria-expanded="false" aria-controls="a1">What makes Brighter Tides different?<span aria-hidden="true">＋</span></button>
            <div class="a" id="a1" hidden>We pair playful coaching with proven habit science and simple protocols. No 30-step routines—just the next best step that fits your life.</div>
          </div>
          <div class="card" role="listitem">
            <button class="q" aria-expanded="false" aria-controls="a2">Do you work virtually or in person?<span aria-hidden="true">＋</span></button>
            <div class="a" id="a2" hidden>Most coaching is virtual for flexibility. Select in-person sessions and retreat days are available seasonally in {{CITY}}, {{STATE}}.</div>
          </div>
          <div class="card" role="listitem">
            <button class="q" aria-expanded="false" aria-controls="a3">Is this therapy or medical care?<span aria-hidden="true">＋</span></button>
            <div class="a" id="a3" hidden>Coaching complements—not replaces—licensed medical or mental health care. We gladly collaborate with your providers.</div>
          </div>
          <div class="card" role="listitem">
            <button class="q" aria-expanded="false" aria-controls="a4">What results can I expect?<span aria-hidden="true">＋</span></button>
            <div class="a" id="a4" hidden>Clients commonly report steadier energy, better sleep, reduced stress reactivity, and more joyful routines within 2–6 weeks.</div>
          </div>
        </div>
      </div>
    </section>

    <section class="section" aria-labelledby="newsletter">
      <div class="wrap">
        <div class="newsletter">
          <span id="newsletter" class="eyebrow">Free guide</span>
          <h2>Steady Energy Playbook</h2>
          <p class="subtle">Grab our 7-minute guide to smoother days: caffeine timing, micro-breaks, and “tide checks.” Delivered to your inbox.</p>
          <form novalidate data-newsletter>
            <label class="sr-only" for="name">Name</label>
            <input id="name" name="name" type="text" placeholder="Your name" autocomplete="name" />
            <label class="sr-only" for="email">Email</label>
            <input id="email" name="email" type="email" placeholder="you@example.com" required inputmode="email" />
            <button class="cta" type="submit">Send my guide</button>
            <div class="hint" aria-live="polite" data-hint></div>
          </form>
        </div>
      </div>
    </section>

    <section class="section" aria-labelledby="cta">
      <div class="wrap cta-row">
        <div>
          <span id="cta" class="eyebrow">Ready when you are</span>
          <h2>Book a friendly check-in</h2>
          <p class="subtle">No pressure. Just clarity. Let’s map your next step together.</p>
        </div>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </section>
  </main>

  <footer>
    <div class="wrap foot">
      <div>
        <div class="brand" aria-label="{{BUSINESS_NAME}} footer">
          <span class="brand-logo" aria-hidden="true"></span>
          <span><b>Brighter Tides</b> Wellness</span>
        </div>
        <small>Ocean-inspired coaching for grounded, playful health.</small>
      </div>
      <div>
        <h3 style="margin-top:0">Visit</h3>
        <p class="subtle">{{ADDRESS}}<br/>{{CITY}}, {{STATE}} {{ZIP}}</p>
        <p class="subtle">Hours: {{HOURS}}</p>
      </div>
      <div>
        <h3 style="margin-top:0">Contact</h3>
        <p class="subtle">Call: <a href="tel:{{PHONE}}">{{PHONE}}</a><br/>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </div>
    <div class="wrap" style="padding:0 20px 24px"><small class="subtle">© <span id="year"></span> {{BUSINESS_NAME}}. All rights reserved.</small></div>
  </footer>

  <script>
    (function(){
      const nav = document.querySelector('.nav');
      const btn = document.querySelector('[data-nav-toggle]');
      if(btn){
        btn.addEventListener('click', ()=>{
          const open = nav.getAttribute('data-open') === 'true';
          nav.setAttribute('data-open', String(!open));
          btn.setAttribute('aria-expanded', String(!open));
        });
      }
      // Smooth scroll for hash links
      document.addEventListener('click', (e)=>{
        const a = e.target.closest('a[href^="#"]');
        if(!a) return;
        const id = a.getAttribute('href').slice(1);
        const el = document.getElementById(id);
        if(el){
          e.preventDefault();
          const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
          el.scrollIntoView({behavior: prefersReduced ? 'auto':'smooth', block:'start'});
          el.focus({preventScroll:true});
        }
      });
      // FAQ accordion
      document.querySelectorAll('.faq .q').forEach(btn=>{
        btn.addEventListener('click', ()=>{
          const id = btn.getAttribute('aria-controls');
          const panel = document.getElementById(id);
          const expanded = btn.getAttribute('aria-expanded') === 'true';
          btn.setAttribute('aria-expanded', String(!expanded));
          panel.hidden = expanded;
        });
      });
      // Newsletter validation hints
      const form = document.querySelector('[data-newsletter]');
      const hint = document.querySelector('[data-hint]');
      if(form){
        form.addEventListener('submit', (e)=>{
          const email = form.querySelector('input[type="email"]');
          if(!email.value || !email.checkValidity()){
            e.preventDefault();
            hint.textContent = 'Please enter a valid email so we can send your guide.';
          } else {
            hint.textContent = 'Thanks! We\'ll send your guide shortly.';
          }
        });
      }
      // Year
      const y = document.getElementById('year');
      if(y) y.textContent = new Date().getFullYear();
    })();
  </script>
</body>
</html>"}
